def is_regular_sequence(beads, k):
    n = len(beads)
    for i in range(1, n + 1):
        a_length = i // (2 * k + 1)
        b_length = (i // (2 * k + 1)) * k
        if i % (2 * k + 1) == 0:
            a_length -= 1
            b_length -= 1
        if i >= 2 * k + 1 and beads[:i].count(beads[0]) == k + 1 and beads[:i].count(beads[k + 1]) == k:
            return True
    return False

def main():
    n, k = map(int, input().split())
    beads = input().strip()
    result = []

    for i in range(1, n + 1):
        if is_regular_sequence(beads[:i], k):
            result.append('1')
        else:
            result.append('0')

    print(''.join(result))

if __name__ == "__main__":
    main()
